#!/usr/bin/env python
"""Extract CTR-GCN intermediate pose feature maps for downstream fusion.

Default raw output layout is [N, M, C, T, V]. The default hook layer is l4,
which is the last CTR-GCN block before temporal downsampling. With a 13-frame
input, l4 keeps T=13.
"""

import argparse
import importlib
import json
import sys
from collections import OrderedDict
from pathlib import Path

import numpy as np
import torch
import torch.nn.functional as F
import yaml
from torch.utils.data import DataLoader, Dataset


def parse_args():
    parser = argparse.ArgumentParser(description="Extract CTR-GCN pose feature maps.")
    parser.add_argument(
        "--config",
        default="config/etri-p1-p230/ctrgcn_joint_raw_13.yaml",
        help="CTR-GCN config path. Relative paths are resolved from the CTR-GCN root.",
    )
    parser.add_argument(
        "--weights",
        default="work_dir/etri_p1_p230_13frames/xsub/ctrgcn_joint_raw/runs-50-2700.pt",
        help="CTR-GCN weight path. Relative paths are resolved from the CTR-GCN root.",
    )
    parser.add_argument(
        "--data",
        default="data/etri/ETRI_P1_P230_CS_raw_uniform13_712.npz",
        help="Input npz generated by split_etri_npz_712.py.",
    )
    parser.add_argument(
        "--split",
        default="train",
        choices=["train", "val", "test", "test_seen"],
        help="Split to extract.",
    )
    parser.add_argument("--hook-layer", default="l4", help="Module name to hook, e.g. l4, l7, l10.")
    parser.add_argument(
        "--feature-mode",
        choices=["adapted", "raw"],
        default="raw",
        help="adapted saves [N,25,13,6,6]. raw saves the hooked CTR-GCN feature map.",
    )
    parser.add_argument(
        "--output",
        default="data/etri/ETRI_P1_P230_CS_raw_uniform13_712_train_l4_raw_NMCTV.npy",
        help="Output .npy path for feature maps.",
    )
    parser.add_argument(
        "--label-output",
        default=None,
        help="Optional label .npy path. Defaults to <output_stem>_labels.npy.",
    )
    parser.add_argument(
        "--name-output",
        default=None,
        help="Optional sample-name .npy path. Defaults to <output_stem>_sample_names.npy when names exist.",
    )
    parser.add_argument("--batch-size", type=int, default=128)
    parser.add_argument("--num-worker", type=int, default=4)
    parser.add_argument("--device", default="cuda:0", help="cuda device or cpu.")
    parser.add_argument("--window-size", type=int, default=13, help="Input frames sent to CTR-GCN.")
    parser.add_argument("--out-frames", type=int, default=13)
    parser.add_argument("--out-joints", type=int, default=25)
    parser.add_argument("--out-size", type=int, default=6, help="Spatial output size H=W.")
    parser.add_argument(
        "--layout",
        choices=["NCTHW", "NTCHW"],
        default="NCTHW",
        help="NCTHW saves [N,25,13,6,6]; NTCHW saves [N,13,25,6,6].",
    )
    parser.add_argument(
        "--raw-layout",
        choices=["NMCTV", "NCTVM", "NCTV", "NMC"],
        default="NMCTV",
        help=(
            "Raw output layout. NMCTV=[N,M,C,T,V], NCTVM=[N,C,T,V,M], "
            "NCTV reduces persons with --person-reduce, NMC flattens T,V to [N,M,C,T*V]."
        ),
    )
    parser.add_argument("--dtype", choices=["float32", "float16"], default="float32")
    parser.add_argument("--person-reduce", choices=["mean", "max", "first"], default="mean")
    parser.add_argument("--max-batches", type=int, default=None, help="Optional smoke-test limit.")
    parser.add_argument("--pin-memory", action="store_true", help="Pin host memory for CUDA extraction.")
    return parser.parse_args()


def resolve_path(path, repo_root):
    path = Path(path)
    return path if path.is_absolute() else repo_root / path


def import_class(name):
    module_name, class_name = name.rsplit(".", 1)
    module = importlib.import_module(module_name)
    return getattr(module, class_name)


def get_module_by_name(model, name):
    module = model
    for part in name.split("."):
        if part.isdigit():
            module = module[int(part)]
        else:
            module = getattr(module, part)
    return module


def load_state_dict(path, device):
    try:
        weights = torch.load(path, map_location=device, weights_only=False)
    except TypeError:
        weights = torch.load(path, map_location=device)
    if isinstance(weights, dict) and "state_dict" in weights:
        weights = weights["state_dict"]
    return OrderedDict((key.split("module.")[-1], value) for key, value in weights.items())


def valid_crop_resize(data_numpy, valid_frame_num, window_size):
    """Deterministic center crop with p=1.0, matching feeder_ntu's tensor layout."""
    channels, total_frames, num_joints, num_person = data_numpy.shape
    valid = max(1, min(int(valid_frame_num), total_frames))
    data = data_numpy[:, :valid, :, :]
    if data.shape[1] == window_size:
        return data

    data_tensor = torch.tensor(data, dtype=torch.float32)
    data_tensor = data_tensor.permute(0, 2, 3, 1).contiguous().view(channels * num_joints * num_person, valid)
    data_tensor = data_tensor[None, None, :, :]
    data_tensor = F.interpolate(
        data_tensor,
        size=(channels * num_joints * num_person, window_size),
        mode="bilinear",
        align_corners=False,
    ).squeeze(0).squeeze(0)
    return (
        data_tensor.contiguous()
        .view(channels, num_joints, num_person, window_size)
        .permute(0, 3, 1, 2)
        .contiguous()
        .numpy()
    )


class EtriNpzSplit(Dataset):
    def __init__(self, data_path, split="train", window_size=13):
        self.data_path = data_path
        self.split = split
        self.window_size = window_size
        npz = np.load(data_path, allow_pickle=True)

        self.x = npz[f"x_{split}"]
        self.y = npz[f"y_{split}"]
        self.actions = npz[f"{split}_action"] if f"{split}_action" in npz.files else None
        if self.y.ndim == 2:
            self.labels = self.y.argmax(axis=1).astype(np.int64)
            missing_label_rows = np.flatnonzero(self.y.sum(axis=1) <= 0)
            if len(missing_label_rows) > 0:
                if self.actions is None:
                    raise ValueError(
                        f"{data_path}:{split} has {len(missing_label_rows)} zero one-hot label rows "
                        "and no action metadata to recover them."
                    )
                self.labels[missing_label_rows] = np.asarray(
                    [self._label_from_action(self.actions[index]) for index in missing_label_rows],
                    dtype=np.int64,
                )
        else:
            self.labels = self.y.astype(np.int64)
        self.frames = npz[f"{split}_frames"] if f"{split}_frames" in npz.files else None
        self.sample_names = npz[f"{split}_sample_name"] if f"{split}_sample_name" in npz.files else None

        num_samples, num_frames, vector_dim = self.x.shape
        expected_dim = 2 * 25 * 3
        if vector_dim != expected_dim:
            raise ValueError(f"Expected input vector dim {expected_dim}, got {vector_dim}")
        self.num_samples = num_samples
        self.num_frames = num_frames

    @staticmethod
    def _label_from_action(action):
        action = action.decode("utf-8") if isinstance(action, bytes) else str(action)
        digits = "".join(ch for ch in action if ch.isdigit())
        if not digits:
            raise ValueError(f"Cannot recover label from action value: {action}")
        return int(digits) - 1

    def __len__(self):
        return self.num_samples

    def __getitem__(self, index):
        data_numpy = self.x[index].reshape(self.num_frames, 2, 25, 3).transpose(3, 0, 2, 1)
        data_numpy = np.array(data_numpy, dtype=np.float32)
        valid_frame_num = (
            int(self.frames[index])
            if self.frames is not None
            else int(np.sum(data_numpy.sum(0).sum(-1).sum(-1) != 0))
        )
        data_numpy = valid_crop_resize(data_numpy, valid_frame_num, self.window_size)
        return data_numpy, int(self.labels[index]), int(index)


def adapt_to_pose_feature_map(features, batch_size, num_person, out_frames, out_joints, out_size, person_reduce):
    """Convert hooked CTR-GCN features to [N, out_joints, out_frames, out_size, out_size].

    Hooked CTR-GCN tensors have shape [N*M, C, T, V]. The adapter treats V as
    joints, reduces multiple persons, then compresses each joint's C-dimensional
    hidden vector to a 6x6 map using adaptive average pooling over C.
    """
    if features.dim() != 4:
        raise ValueError(f"Expected hooked tensor [N*M, C, T, V], got {tuple(features.shape)}")

    nm, channels, frames, joints = features.shape
    expected_nm = batch_size * num_person
    if nm != expected_nm:
        raise ValueError(f"Hooked batch mismatch: got {nm}, expected {expected_nm}")

    features = features.view(batch_size, num_person, channels, frames, joints)
    if person_reduce == "mean":
        features = features.mean(dim=1)
    elif person_reduce == "max":
        features = features.max(dim=1).values
    else:
        features = features[:, 0]

    if frames != out_frames or joints != out_joints:
        features = F.interpolate(features, size=(out_frames, out_joints), mode="bilinear", align_corners=False)

    features = features.permute(0, 3, 2, 1).contiguous()  # [N, V, T, C]
    pooled = F.adaptive_avg_pool1d(
        features.view(-1, 1, channels),
        out_size * out_size,
    )
    return pooled.view(batch_size, out_joints, out_frames, out_size, out_size)


def reduce_person(features, person_reduce):
    if person_reduce == "mean":
        return features.mean(dim=1)
    if person_reduce == "max":
        return features.max(dim=1).values
    return features[:, 0]


def raw_feature_from_hook(features, batch_size, num_person, raw_layout, person_reduce):
    """Convert hooked [N*M,C,T,V] into a sample-aligned raw layout."""
    if features.dim() != 4:
        raise ValueError(f"Expected hooked tensor [N*M, C, T, V], got {tuple(features.shape)}")

    nm, channels, frames, joints = features.shape
    expected_nm = batch_size * num_person
    if nm != expected_nm:
        raise ValueError(f"Hooked batch mismatch: got {nm}, expected {expected_nm}")

    features = features.view(batch_size, num_person, channels, frames, joints)
    if raw_layout == "NMCTV":
        return features.contiguous()
    if raw_layout == "NCTVM":
        return features.permute(0, 2, 3, 4, 1).contiguous()
    if raw_layout == "NCTV":
        return reduce_person(features, person_reduce).contiguous()
    if raw_layout == "NMC":
        return features.view(batch_size, num_person, channels, frames * joints).contiguous()
    raise ValueError(f"Unsupported raw layout: {raw_layout}")


def main():
    args = parse_args()
    repo_root = Path(__file__).resolve().parents[1]
    sys.path.insert(0, str(repo_root))
    sys.path.insert(0, str(repo_root / "torchlight"))

    config_path = resolve_path(args.config, repo_root)
    weights_path = resolve_path(args.weights, repo_root)
    data_path = resolve_path(args.data, repo_root)
    output_path = resolve_path(args.output, repo_root)
    label_output = resolve_path(args.label_output, repo_root) if args.label_output else output_path.with_name(output_path.stem + "_labels.npy")
    name_output = resolve_path(args.name_output, repo_root) if args.name_output else output_path.with_name(output_path.stem + "_sample_names.npy")
    metadata_path = output_path.with_suffix("").as_posix() + "_metadata.json"

    with open(config_path, "r", encoding="utf-8") as handle:
        config = yaml.safe_load(handle) or {}

    device = torch.device(args.device if args.device == "cpu" or torch.cuda.is_available() else "cpu")
    model_class = import_class(config["model"])
    model = model_class(**config["model_args"]).to(device)
    state_dict = load_state_dict(weights_path, device)
    model.load_state_dict(state_dict, strict=True)
    model.eval()

    captured = {}

    def hook_fn(_module, _inputs, output):
        captured["features"] = output.detach()

    hook = get_module_by_name(model, args.hook_layer).register_forward_hook(hook_fn)

    dataset = EtriNpzSplit(data_path, split=args.split, window_size=args.window_size)
    loader = DataLoader(
        dataset,
        batch_size=args.batch_size,
        shuffle=False,
        drop_last=False,
        num_workers=args.num_worker,
        pin_memory=(args.pin_memory and device.type == "cuda"),
    )

    output_path.parent.mkdir(parents=True, exist_ok=True)
    output_dtype = np.float16 if args.dtype == "float16" else np.float32
    max_samples = len(dataset)
    if args.max_batches is not None:
        max_samples = min(max_samples, args.max_batches * args.batch_size)
    if args.feature_mode == "adapted":
        output_shape = (
            (max_samples, args.out_joints, args.out_frames, args.out_size, args.out_size)
            if args.layout == "NCTHW"
            else (max_samples, args.out_frames, args.out_joints, args.out_size, args.out_size)
        )
        feature_map = np.lib.format.open_memmap(
            output_path,
            mode="w+",
            dtype=output_dtype,
            shape=output_shape,
        )
    else:
        output_shape = None
        feature_map = None

    labels = []
    offset = 0
    first_hook_shape = None
    first_output_shape = None

    with torch.no_grad():
        for batch_idx, (data, label, _index) in enumerate(loader):
            if args.max_batches is not None and batch_idx >= args.max_batches:
                break
            data = data.float().to(device, non_blocking=(device.type == "cuda"))
            batch_size = data.size(0)
            if offset + batch_size > max_samples:
                batch_size = max_samples - offset
                data = data[:batch_size]
                label = label[:batch_size]
            captured.clear()
            _ = model(data)
            if "features" not in captured:
                raise RuntimeError(f"Hook layer {args.hook_layer} did not capture any output")

            hooked = captured["features"]
            if args.feature_mode == "raw":
                output_batch = raw_feature_from_hook(
                    hooked,
                    batch_size=batch_size,
                    num_person=data.size(-1),
                    raw_layout=args.raw_layout,
                    person_reduce=args.person_reduce,
                )
            else:
                output_batch = adapt_to_pose_feature_map(
                    hooked,
                    batch_size=batch_size,
                    num_person=data.size(-1),
                    out_frames=args.out_frames,
                    out_joints=args.out_joints,
                    out_size=args.out_size,
                    person_reduce=args.person_reduce,
                )
                if args.layout == "NTCHW":
                    output_batch = output_batch.permute(0, 2, 1, 3, 4).contiguous()

            if first_hook_shape is None:
                first_hook_shape = list(hooked.shape)
                first_output_shape = list(output_batch.shape)
                if args.feature_mode == "raw":
                    output_shape = (max_samples,) + tuple(first_output_shape[1:])
                    feature_map = np.lib.format.open_memmap(
                        output_path,
                        mode="w+",
                        dtype=output_dtype,
                        shape=output_shape,
                    )

            feature_map[offset:offset + batch_size] = output_batch.cpu().numpy().astype(output_dtype, copy=False)
            labels.append(label.numpy())
            offset += batch_size
            print(f"batch {batch_idx + 1}/{len(loader)} -> saved {offset}/{max_samples}", flush=True)
            if offset >= max_samples:
                break

    hook.remove()
    del feature_map

    labels = np.concatenate(labels, axis=0)[:offset]
    np.save(label_output, labels)
    if dataset.sample_names is not None:
        np.save(name_output, dataset.sample_names[:offset])

    metadata = {
        "config": str(config_path),
        "weights": str(weights_path),
        "data": str(data_path),
        "split": args.split,
        "hook_layer": args.hook_layer,
        "feature_mode": args.feature_mode,
        "window_size": args.window_size,
        "person_reduce": args.person_reduce,
        "layout": args.layout,
        "raw_layout": args.raw_layout,
        "hooked_shape_first_batch": first_hook_shape,
        "output_shape_first_batch": first_output_shape,
        "output": str(output_path),
        "output_shape": (
            ([offset] + list(output_shape[1:]))
            if output_shape is not None
            else None
        ),
        "output_dtype": args.dtype,
        "labels": str(label_output),
        "sample_names": str(name_output) if dataset.sample_names is not None else None,
        "adapter": (
            "raw: hooked [N*M,C,T,V] reshaped according to --raw-layout; "
            "adapted: person reduce -> optional T,V resize -> adaptive average pool hidden channels to 6x6 per joint"
        ),
    }
    with open(metadata_path, "w", encoding="utf-8") as handle:
        json.dump(metadata, handle, indent=2, ensure_ascii=False)

    print(f"Saved feature maps: {output_path}")
    print(f"Saved labels: {label_output}")
    if dataset.sample_names is not None:
        print(f"Saved sample names: {name_output}")
    print(f"Saved metadata: {metadata_path}")


if __name__ == "__main__":
    main()
